// Webhook output has the request body under $json.body.
// Flatten the envelope and its payload into one item.
const b = $input.first().json.body || {};
if (!b.runId) throw new Error('Missing runId in the request body');
return [{
  json: {
    runId: b.runId,
    ownerId: b.ownerId ?? null,
    jobId: b.jobId ?? null,
    agentId: b.agentId ?? null,
    ...(b.payload || {}),
  },
}];

parameters.query:
SELECT id, title, description, category, repo_url, base_commit,
       (SELECT coalesce(max(version), 0) FROM acceptance_specs WHERE job_id = $1::uuid) AS last_version
FROM jobs WHERE id = $1::uuid;

