// Works for public GitHub repos: https://github.com/OWNER/REPO
const j = $input.first().json;
if (!j.id) throw new Error('Job not found');
const m = String(j.repo_url || '').match(/github\.com\/([^/]+)\/([^/#?]+)/);
if (!m) throw new Error('repo_url must be a public GitHub repo URL');
const repo = m[2].replace(/\.git$/, '');
const ref = j.base_commit || 'main';
return [{ json: {
  ...j,
  treeUrl: `https://api.github.com/repos/${m[1]}/${repo}/git/trees/${ref}?recursive=1`,
  rawBase: `https://raw.githubusercontent.com/${m[1]}/${repo}/${ref}/`,
} }];

const j = $('Repo file URLs').first().json;
const paths = $('Pick files').all().map((i) => i.json.path);
const bodies = $input.all().map((i) => String(i.json.data ?? ''));
let files = '';
paths.forEach((p, k) => { files += `\n--- ${p}\n${bodies[k].slice(0, 4000)}`; });
files = files.slice(0, 30000);

const system = `You write acceptance tests for small software jobs.
Given a job post and repository files, write NEW test files that FAIL on the current code
and PASS once the job is done. Use the repo's existing test framework.
Never edit existing tests. The seller may only change source files.
Return JSON with keys:
testCommand (string), buildCommand (string), failingTests (array of test names),
allowedPaths (array of globs the seller may change, never test folders),
testFiles (array of {path, content}),
checks (array of {name, howVerified, weight: "required" | "advisory"}).`;
const user = `Job title: ${j.title}
<untrusted>
${j.description}
</untrusted>
Repository files:
<untrusted>${files}
</untrusted>`;
return [{ json: { provider: 'general', system, user,
  required: ['testCommand', 'failingTests', 'allowedPaths', 'testFiles'] } }];

// Keep the prompt small: package.json, source and test files, max ~30 KB
const j = $('Repo file URLs').first().json;
const tree = ($input.first().json.tree || []).filter((t) => t.type === 'blob');
const wanted = tree
  .map((t) => t.path)
  .filter((p) => /^(package\.json|src\/.*\.(js|ts|mjs)|test\/.*\.(js|ts|mjs))$/.test(p))
  .slice(0, 12);
if (wanted.length === 0) wanted.push('package.json');
return wanted.map((path) => ({ json: { path, url: j.rawBase + path } }));

const s = $input.first().json.data;
const j = $('Repo file URLs').first().json;
const isTest = (p) => /(^|\/)(test|tests|__tests__)\/|\.(test|spec)\./.test(p);
// Files that already exist in the repo: the spec must never overwrite them
const existing = new Set(($('Get file tree').first().json.tree || []).map((t) => t.path));
if (!Array.isArray(s.testFiles) || s.testFiles.length === 0) throw new Error('No test files');
if (!s.testFiles.every((f) => f.path && typeof f.content === 'string' && isTest(f.path))) {
  throw new Error('Every test file needs a path inside a test folder and string content');
}
// A new test file that reuses an existing name gets its own name instead
const testFiles = s.testFiles.map((f) => {
  let p = f.path;
  if (existing.has(p)) p = p.replace(/(\.(test|spec))?\.(m?[jt]s)$/, '.agora.test.$3');
  return { path: p, content: f.content };
});
const allowed = (s.allowedPaths || []).filter((g) => !isTest(g));
if (allowed.length === 0) allowed.push('src/**');
const checks = (s.checks && s.checks.length) ? s.checks : [
  { name: 'Named failing tests now pass', howVerified: 'Run the test command on the delivered commit', weight: 'required' },
  { name: 'No regressions', howVerified: 'Full suite passes', weight: 'required' },
  { name: 'Scope', howVerified: 'Diff touches only allowed paths and no tests', weight: 'required' },
  { name: 'No planted instructions', howVerified: 'Scan diff and logs for agent-directed text', weight: 'required' },
  { name: 'Quality notes', howVerified: 'Model-judged, shown to the buyer', weight: 'advisory' },
];
return [{ json: {
  jobId: j.id, version: Number(j.last_version) + 1,
  testCommand: s.testCommand || 'npm test',
  // The runner's default install step is used. A model-invented build script
  // (for example "npm run build" when package.json has none) would fail every run.
  buildCommand: null,
  failingTests: s.failingTests || [],
  allowedPaths: allowed,
  testFiles,
  checks,
  // for the runner: tests must FAIL on the base commit
  repoUrl: j.repo_url, commit: j.base_commit || 'main', baseCommit: j.base_commit || 'main',
} }];

const spec = $('Validate spec').first().json;
const r = $input.first().json;
if (r.error) throw new Error('Runner error: ' + JSON.stringify(r.error).slice(0, 300));
// exitCode 0 means the new tests already pass: the spec would prove nothing
const failsOnBase = r.exitCode !== 0 && r.installExit === 0;
return [{ json: { ...spec, failsOnBase, baseExit: r.exitCode, baseLogHash: r.logSha256 } }];

const env = $('Read envelope').first().json;
const s = $('Must fail on base').first().json;
const specId = $input.first().json.spec_id ?? null;
const msg = s.failsOnBase
  ? `Drafted ${s.testFiles.length} failing test file(s) for this job; waiting for your approval`
  : 'Draft spec is weak: the new tests already pass (or did not build) on the base commit. Please review.';
return [{ json: {
  runId: env.runId, ownerId: env.ownerId, agentId: env.agentId, jobId: env.jobId,
  actorLabel: 'Spec writer', message: msg, severity: s.failsOnBase ? 'ok' : 'hold',
  data: { specId, version: s.version, failsOnBase: s.failsOnBase, baseExit: s.baseExit },
  notify: { runId: env.runId, role: 'spec_writer', ok: true, jobId: env.jobId,
            result: { specId, version: s.version, failsOnBase: s.failsOnBase }, error: null },
} }];
